mapper.update:
update driver
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, id_card = #{idCard}, driving_years = #{drivingYears}, photo_url = #{photoUrl}, is_banned = #{isBanned}, average_rating = #{averageRating}, rating_count = #{ratingCount}, update_time = #{updateTime},
where id = #{id}

mapper.select:
SELECT
id, username, name, gender, phone, id_card, driving_years, photo_url, is_banned, average_rating, rating_count,
create_time, update_time
FROM
driver


        AND username LIKE CONCAT('%', #{username}, '%')


        AND name LIKE CONCAT('%', #{name}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND is_banned = #{isBanned}


        AND create_time >= #{createTimeStart}


        AND create_time <= #{createTimeEnd}


        AND average_rating >= #{minAverageRating}


        AND average_rating <= #{maxAverageRating}


        AND rating_count >= #{minRatingCount}


        AND rating_count <= #{maxRatingCount}


        AND driving_years >= #{minDrivingYears}


        AND driving_years <= #{maxDrivingYears}


ORDER BY id ASC
